import{_ as n,o as r,c as a,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const i="/bilder/reportverwaltung/tutorials-mailversand-reporting-1.png",l="/bilder/reportverwaltung/tutorials-mailversand-reporting-2.png",c=JSON.parse('{"title":"Einen Report per E-Mail versenden und teilen","description":"","frontmatter":{"title":"Einen Report per E-Mail versenden und teilen","source_pageid":1570,"source_revision":6561},"headers":[],"relativePath":"reporting/reportverwaltung/einen-report-per-e-mail-versenden-und-teilen.md","filePath":"reporting/reportverwaltung/einen-report-per-e-mail-versenden-und-teilen.md"}'),d={name:"reporting/reportverwaltung/einen-report-per-e-mail-versenden-und-teilen.md"};function s(o,e,p,g,h,u){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="einen-report-per-e-mail-versenden-und-teilen" tabindex="-1">Einen Report per E-Mail versenden und teilen <a class="header-anchor" href="#einen-report-per-e-mail-versenden-und-teilen" aria-label="Permalink to &quot;Einen Report per E-Mail versenden und teilen&quot;">​</a></h1><p>Sie können eine Reportausgabe als E-Mail-Anhang vorbereiten. Dabei lassen sich Empfängeradresse, Betreff und Nachrichtentext im Versanddialog anpassen.</p><h2 id="den-versanddialog-offnen" tabindex="-1">Den Versanddialog öffnen <a class="header-anchor" href="#den-versanddialog-offnen" aria-label="Permalink to &quot;Den Versanddialog öffnen&quot;">​</a></h2><ol><li>Erzeugen Sie den gewünschten Report.</li><li>Klicken Sie auf <strong>Als Email versenden</strong>.</li></ol><p><a href="/bilder/reportverwaltung/tutorials-mailversand-reporting-1.png"><img src="'+i+'" alt="Versenden von Reports als Emailanhang." loading="lazy"></a></p><p><em>Versenden von Reports als Emailanhang.</em></p><h2 id="empfanger-und-nachricht-eintragen" tabindex="-1">Empfänger und Nachricht eintragen <a class="header-anchor" href="#empfanger-und-nachricht-eintragen" aria-label="Permalink to &quot;Empfänger und Nachricht eintragen&quot;">​</a></h2><p><a href="/bilder/reportverwaltung/tutorials-mailversand-reporting-2.png"><img src="'+l+'" alt="Versenden von Reports als Emailanhang." loading="lazy"></a></p><p><em>Versenden von Reports als Emailanhang.</em></p><ol><li>Tragen Sie die Empfängeradresse ein. Die beiden Schaltflächen übernehmen wahlweise die Adresse der Schülerin oder des Schülers aus <strong>Individualdaten I</strong> oder die unter den Erziehern hinterlegte Adresse.</li><li>Passen Sie bei Bedarf <strong>Betreff</strong> und <strong>Emailtext</strong> an.</li><li>Kontrollieren Sie die Empfängeradresse und den Nachrichtentext vor dem Versenden.</li></ol><h2 id="den-standardtext-andern" tabindex="-1">Den Standardtext ändern <a class="header-anchor" href="#den-standardtext-andern" aria-label="Permalink to &quot;Den Standardtext ändern&quot;">​</a></h2><p>Der im Dialog vorbelegte Text wird unter <strong>Verwaltung → Einstellungen → Interne Texte</strong> festgelegt. Weitere Angaben finden Sie unter <a href="/reporting/reportdesigner/interne-texte-verwaltung-einstellungen.html">Interne Texte</a>.</p><p>Wenn Sie schülerindividuelle Reportausgaben gesammelt versenden möchten, verwenden Sie die Anleitung <a href="/reporting/reportdesigner/serien-e-mail-versand.html">Serien-E-Mail-Versand</a>.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Einen_Report_per_E-Mail_versenden_und_teilen" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6561.</p>',15)])])}const f=n(d,[["render",s]]);export{c as __pageData,f as default};
